import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { writeFile } from "node:fs/promises";
import { join } from "node:path";

async function main() {
  let writerWorkspace: any;
  let readerWorkspace: any;

  let writer_put_ok = false;
  let readonly_put_blocked = false;

  try {
    console.log("Creating workspaces concurrently...");
    const [writerRes, readerRes] = await Promise.all([
      createWorkspace("writer-ws", { credentials: { role: "Editor" } }),
      createWorkspace("reader-ws", { credentials: { role: "ReadOnly" } }),
    ]);

    if (writerRes.error) {
      throw new Error(`Failed to create writer workspace: ${writerRes.error.message}`);
    }
    if (readerRes.error) {
      throw new Error(`Failed to create reader workspace: ${readerRes.error.message}`);
    }

    writerWorkspace = writerRes.data;
    readerWorkspace = readerRes.data;

    if (!writerWorkspace.bucket || !writerWorkspace.credentials?.accessKeyId || !writerWorkspace.credentials?.secretAccessKey) {
      throw new Error("Writer workspace response missing required fields");
    }
    if (!readerWorkspace.bucket || !readerWorkspace.credentials?.accessKeyId || !readerWorkspace.credentials?.secretAccessKey) {
      throw new Error("Reader workspace response missing required fields");
    }

    console.log("Workspaces created successfully.");

    const writerS3 = new S3Client({
      region: "auto",
      endpoint: "https://t3.storage.dev",
      credentials: {
        accessKeyId: writerWorkspace.credentials.accessKeyId,
        secretAccessKey: writerWorkspace.credentials.secretAccessKey,
      },
    });

    const readerS3 = new S3Client({
      region: "auto",
      endpoint: "https://t3.storage.dev",
      credentials: {
        accessKeyId: readerWorkspace.credentials.accessKeyId,
        secretAccessKey: readerWorkspace.credentials.secretAccessKey,
      },
    });

    // Role check: Editor
    try {
      console.log("Attempting PutObject with Editor client...");
      await writerS3.send(new PutObjectCommand({
        Bucket: writerWorkspace.bucket,
        Key: "note.txt",
        Body: "hello dual role",
      }));
      writer_put_ok = true;
      console.log("Editor PutObject succeeded.");
    } catch (err) {
      console.error("Editor PutObject failed:", err);
      writer_put_ok = false;
    }

    // Role check: ReadOnly
    try {
      console.log("Attempting PutObject with ReadOnly client...");
      await readerS3.send(new PutObjectCommand({
        Bucket: readerWorkspace.bucket,
        Key: "note.txt",
        Body: "should be blocked",
      }));
      readonly_put_blocked = false;
      console.log("ReadOnly PutObject unexpectedly succeeded.");
    } catch (err: any) {
      console.log("ReadOnly PutObject blocked as expected.");
      const isBlocked = 
        err.name === "AccessDenied" || 
        err.Code === "AccessDenied" || 
        err.name === "NotImplemented" || 
        err.Code === "NotImplemented" || 
        err.$metadata?.httpStatusCode === 403;

      readonly_put_blocked = isBlocked;
      if (!isBlocked) {
        console.error("ReadOnly PutObject failed but not with expected error:", err);
      }
    }

    const result = {
      writer_bucket: "writer-ws",
      reader_bucket: "reader-ws",
      writer_put_ok,
      readonly_put_blocked,
    };

    const resultPath = join("/home/user/dual-role", "result.json");
    await writeFile(resultPath, JSON.stringify(result, null, 2));
    console.log(`Result written to ${resultPath}`);

  } finally {
    console.log("Tearing down workspaces...");
    const teardowns = [];
    if (writerWorkspace) {
      teardowns.push(teardownWorkspace("writer-ws"));
    }
    if (readerWorkspace) {
      teardowns.push(teardownWorkspace("reader-ws"));
    }
    await Promise.all(teardowns);
    console.log("Teardown complete.");
  }
}

main().catch((err) => {
  console.error("Script failed:", err);
  process.exit(1);
});
